mapper.insert:
INSERT INTO ai_conversation_turn (conversation_id, mode, goal, answer, status, result_json)
SELECT #{turn.conversationId}, #{turn.mode}, #{turn.goal}, #{turn.answer}, #{turn.status}, #{turn.resultJson}
FROM ai_conversation WHERE id = #{turn.conversationId} AND user_id = #{userId}
AND lock_token = #{token} AND lock_deadline > #{now}

mapper.select:
SELECT t.id, t.conversation_id, t.mode, t.goal, t.answer, t.status, t.gmt_create
FROM ai_conversation_turn t JOIN ai_conversation c ON c.id = t.conversation_id
WHERE c.id = #{id} AND c.user_id = #{userId}
AND t.id < #{beforeId}
ORDER BY t.id DESC LIMIT 51
